const lv_font_t *html_font_for_px(int px) {
    html_fonts_init();
    if (px >= 22) return &g_html_font_24;
    if (px >= 19) return &g_html_font_20;
    if (px >= 17) return &g_html_font_18;
    if (px >= 15) return &g_html_font_16;
    if (px > 0 && px <= 12) return &g_html_font_12;
    return &g_html_font_14;
}
